<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref } from 'vue';
import { ArrowLeft, ArrowUpRight, Bookmark, Check, Flame, Pause, Play, X } from 'lucide-vue-next';
import { desktop, invoke } from '../bridge.ts';
import { fortunes, wishThemes, emptyJournal, loadJournal, saveJournal, type Journal } from './journal.ts';
import FortuneVessel from './FortuneVessel.vue';
import PondScene from './PondScene.vue';
declare global { interface Window { __XIAOBAN_RITUAL_CONFIG__?: { paused: boolean; fps: 30 | 60 } } }
const scene = ref(new URLSearchParams(location.search).get('ritual') === 'pond' ? 'pond' : 'fortune');
const config = window.__XIAOBAN_RITUAL_CONFIG__;
const paused = ref(config?.paused ?? false), fps = config?.fps ?? 30;
const initialSign = new URLSearchParams(location.search).get('sign');
const validSign = initialSign !== null && /^\d+$/.test(initialSign) && Number(initialSign) < fortunes.length;
const phase = ref<'idle' | 'shaking' | 'result'>(validSign ? 'result' : 'idle'), fortuneId = ref(validSign ? Number(initialSign) : 0), journal = ref<Journal>(emptyJournal());
const current = computed(() => fortunes[fortuneId.value]);
const ready = ref(false), busy = ref(false), error = ref(''), theme = ref<string>('平安'), wish = ref('');
const composer = ref(false), placement = ref({ x: .5, y: .64 }), textarea = ref<HTMLTextAreaElement>();
const drawer = ref<HTMLDialogElement>(), drawerOpen = ref(false), savedButton = ref<HTMLButtonElement>();
let timer: ReturnType<typeof setTimeout> | undefined;
const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
async function load() {
  ready.value = false; error.value = '';
  try { journal.value = await loadJournal(); ready.value = true; } catch (e) { error.value = String(e); }
}
async function persist(next: Journal) {
  if (!ready.value || busy.value) return false;
  busy.value = true; error.value = '';
  try { await saveJournal(next); journal.value = next; return true; }
  catch (e) { error.value = `保存失败：${String(e)}`; return false; }
  finally { busy.value = false; }
}
function drawFortune() {
  if (phase.value === 'shaking') return;
  phase.value = 'shaking';
  const random = crypto.getRandomValues(new Uint32Array(1))[0];
  fortuneId.value = random % fortunes.length;
  timer = setTimeout(async () => { phase.value = 'result'; await nextTick(); savedButton.value?.focus(); }, reduced ? 120 : 1850);
}
async function collect() {
  if (journal.value.saved.includes(fortuneId.value)) return;
  await persist({ ...journal.value, saved: [...journal.value.saved, fortuneId.value] });
}
async function openComposer(point?: { x: number; y: number }) {
  if (!ready.value || busy.value) return;
  if (point) placement.value = point;
  else placement.value = { x: .2 + Math.random() * .6, y: .48 + Math.random() * .28 };
  composer.value = true; await nextTick(); textarea.value?.focus();
}
async function release() {
  if (!wish.value.trim() || journal.value.wishes.length >= 24) return;
  const next = { id: crypto.randomUUID(), text: wish.value.trim(), theme: theme.value, ...placement.value };
  if (await persist({ ...journal.value, wishes: [...journal.value.wishes, next] })) { wish.value = ''; composer.value = false; }
}
async function removeWish(id: string) { await persist({ ...journal.value, wishes: journal.value.wishes.filter(w => w.id !== id) }); }
async function removeFortune(id: number) { await persist({ ...journal.value, saved: journal.value.saved.filter(v => v !== id) }); }
async function showDrawer() { drawerOpen.value = true; await nextTick(); drawer.value?.showModal(); }
function hideDrawer() { drawer.value?.close(); drawerOpen.value = false; }
function showFortune(id: number) { fortuneId.value = id; phase.value = 'result'; hideDrawer(); }
async function close() {
  if (busy.value) return;
  try {
    if (desktop) await invoke('close_ritual_space');
    else { window.close(); if (!window.closed) location.assign('/'); }
  } catch (e) { error.value = `退出失败：${String(e)}`; }
}
function key(event: KeyboardEvent) {
  if (event.key !== 'Escape' || event.isComposing) return;
  if (drawerOpen.value) return; // The native dialog handles Escape and restores focus.
  event.preventDefault();
  if (composer.value) { if (!busy.value) composer.value = false; }
  else void close();
}
function switchScene(next: string) { if (busy.value) return; if (timer) clearTimeout(timer); phase.value = 'idle'; composer.value = false; scene.value = next; }
onMounted(() => { void load(); window.addEventListener('keydown', key); });
onBeforeUnmount(() => { if (timer) clearTimeout(timer); window.removeEventListener('keydown', key); });
</script>
<template>
  <main class="ritual-space" :class="[scene, { 'is-paused': paused }]" :data-paused="paused">
    <PondScene v-if="scene === 'pond'" :paused="paused" :fps="fps" :wishes="journal.wishes" :interactive="ready && !busy && journal.wishes.length < 24" @water="openComposer"/>
    <div v-else class="paper-background"><div class="sun-circle"></div><div class="paper-grain"></div></div>
    <header class="ritual-header"><button class="back-button" :disabled="busy" @click="close"><ArrowLeft :size="16"/><span>返回互动壁纸</span></button><nav class="scene-tabs" aria-label="互动场景"><button :class="{active:scene==='fortune'}" :disabled="busy" @click="switchScene('fortune')">一签好意</button><span>·</span><button :class="{active:scene==='pond'}" :disabled="busy" @click="switchScene('pond')">一池心灯</button></nav><div class="header-tools"><button v-if="scene==='pond'" :aria-label="paused ? '播放水景' : '暂停水景'" @click="paused=!paused"><Play v-if="paused" :size="16"/><Pause v-else :size="16"/></button><button :disabled="!ready || busy" class="journal-button" @click="showDrawer"><Bookmark :size="15"/><span>{{ scene==='fortune' ? '我的好签' : '我的心灯' }}</span></button><button aria-label="退出互动" :disabled="busy" @click="close"><X :size="19"/></button></div></header>
    <div v-if="error" class="ritual-error" role="alert">{{ error }}<button v-if="!ready" @click="load">重新读取</button></div>
    <section v-if="scene==='fortune'" class="fortune-stage">
      <div class="fortune-heading"><span class="eyebrow">GOOD WISHES · 一签好意</span><h1>{{ phase==='result' ? '好意，恰好与你相逢' : '愿你所盼，皆有回响' }}</h1><p>{{ phase==='shaking' ? '让心静一静，好签正在途中。' : '为今天留一点期待，也为自己收下一份祝福。' }}</p></div>
      <div v-if="phase!=='result'" class="fortune-object"><span class="object-poem">所念皆星河<br>所行皆坦途</span><FortuneVessel :shaking="phase==='shaking'"/><span class="tiny-seal">好<br>意</span></div>
      <article v-else class="fortune-result" aria-live="polite"><div class="result-top"><span>心愿集</span><span>第 {{ String(fortuneId+1).padStart(2,'0') }} 签</span></div><div class="result-rule"></div><span class="result-seal">吉</span><h2>{{ current.title }}</h2><p class="result-verse">{{ current.verse }}</p><p class="result-blessing">{{ current.blessing }}</p><div class="result-action"><span>今日小行动</span><p>{{ current.action }}</p></div><span class="result-bottom">愿这份好意，陪你走一小段路。</span></article>
      <div class="fortune-bottom"><template v-if="phase!=='result'"><button class="primary-button cinnabar" :disabled="phase==='shaking'" data-testid="draw-fortune" @click="drawFortune">{{ phase==='shaking' ? '好签正在途中…' : '求一支好签' }}<ArrowUpRight :size="16"/></button><p>把一个小心愿，轻轻放在心里。</p></template><template v-else><div class="result-buttons"><button ref="savedButton" class="primary-button cinnabar" :disabled="!ready || busy || journal.saved.includes(fortuneId)" data-testid="save-fortune" @click="collect"><Check v-if="journal.saved.includes(fortuneId)" :size="15"/><Bookmark v-else :size="15"/>{{ journal.saved.includes(fortuneId) ? '好意已收藏' : busy ? '正在收藏…' : '收下这份好意' }}</button><button class="text-button" @click="phase='idle'">再求一签</button></div><p>一句祝福，一个小小的开始。</p></template></div>
    </section>
    <section v-else class="pond-stage"><div class="pond-heading"><span class="eyebrow">LANTERN WISHES · 一池心灯</span><h1>一灯一愿，岁岁长安</h1><p>让一盏灯，替你照亮心里的愿望。</p></div><div v-if="!composer" class="pond-bottom"><button class="primary-button lantern-button" :disabled="!ready || busy || journal.wishes.length>=24" data-testid="write-wish" @click="openComposer()"><Flame :size="17"/>{{ journal.wishes.length>=24 ? '灯池已满，去心灯册收回一盏' : '放一盏心灯' }}</button><p>点击水面，也可以选择放灯的位置。</p></div><form v-else class="wish-composer" @submit.prevent="release"><div class="composer-title"><div><span>把心愿写在灯里</span><small>不必宏大，平安和欢喜也很好。</small></div><button type="button" aria-label="收起心愿" :disabled="busy" @click="composer=false"><X :size="18"/></button></div><div class="theme-choices" role="group" aria-label="心愿主题"><button v-for="value in wishThemes" :key="value" type="button" :aria-pressed="theme===value" :class="{selected:theme===value}" :disabled="busy" @click="theme=value">{{ value }}</button></div><label class="sr-only" for="wish-text">你的心愿</label><textarea id="wish-text" ref="textarea" v-model="wish" maxlength="60" :disabled="busy" placeholder="愿我惦念的人，平安喜乐。" rows="3"/><div class="composer-footer"><span>{{ wish.length }} / 60 · 点击水面选位置</span><button class="primary-button lantern-button" :disabled="!wish.trim() || busy || !ready" type="submit" data-testid="release-wish">{{ busy ? '正在放灯…' : '让心灯入水' }}<ArrowUpRight :size="15"/></button></div></form></section>
    <footer class="ritual-footer"><span>{{ scene==='fortune' ? '心有所愿 · 日有所暖' : `灯火可亲 · 已寄 ${journal.wishes.length} 份心愿` }}</span><span>Esc 返回</span></footer>
    <dialog ref="drawer" class="journal-drawer" @close="drawerOpen=false" @cancel="drawerOpen=false"><header><div><span class="eyebrow">A LITTLE COLLECTION</span><h2>{{ scene==='fortune' ? '收藏的好意' : '寄出的心愿' }}</h2></div><button aria-label="关闭收藏" @click="hideDrawer"><X :size="20"/></button></header><p class="drawer-note">留在这台电脑上，随时回来看看。</p><template v-if="scene==='fortune'"><p v-if="!journal.saved.length" class="empty-journal">还没有收藏的好签。<br>遇到喜欢的一句，就把它留下吧。</p><article v-for="id in journal.saved" :key="id" class="journal-entry"><button class="saved-entry" @click="showFortune(id)"><small>第 {{ String(id+1).padStart(2,'0') }} 签</small><strong>{{ fortunes[id].title }}</strong><span>{{ fortunes[id].blessing }}</span></button><button class="remove-entry" :disabled="busy" @click="removeFortune(id)">取消收藏</button></article></template><template v-else><p v-if="!journal.wishes.length" class="empty-journal">水面还在等第一盏心灯。<br>愿你的心事，都有温柔的归处。</p><article v-for="item in [...journal.wishes].reverse()" :key="item.id" class="journal-entry"><span class="wish-theme"><Flame :size="13"/>{{ item.theme }}</span><p>{{ item.text }}</p><button class="remove-entry" :disabled="busy" @click="removeWish(item.id)">收回这盏灯</button></article></template></dialog>
  </main>
</template>
