r-color:#c6a46e80;background:#c6a46e13}.wish-composer textarea{display:block;box-sizing:border-box;width:100%;padding:13px 14px;color:#ecdfc2;border:1px solid #a5b8aa33;background:#041b2270;border-radius:7px;resize:none;font-family:inherit;font-size:13px;line-height:1.8;outline:none}.wish-composer textarea:focus{border-color:#c9b380}.wish-composer textarea::placeholder{color:#77928a}.composer-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:16px}.composer-footer>span{font-size:9px;color:#9bb1a2}.composer-footer .primary-button{font-size:11px;padding:10px 13px;gap:8px}.ritual-footer{position:absolute;bottom:24px;left:35px;right:35px;display:flex;justify-content:space-between;font-size:10px;letter-spacing:2px;opacity:.5;pointer-events:none}.ritual-error{position:absolute;z-index:6;left:50%;top:80px;transform:translateX(-50%);background:#fff4e6;color:#934838;padding:10px 20px;border:1px solid #bd8b7c;border-radius:8px;font-size:12px;max-width:75vw;overflow-wrap:anywhere}.ritual-error button{border:0;background:none;color:inherit;text-decoration:underline;margin-left:15px;cursor:pointer}.journal-drawer{position:fixed;inset:0 0 0 auto;margin:0;height:100%;max-height:100%;box-sizing:border-box;width:min(400px,90vw);max-width:90vw;padding:36px 28px;background:#f6f0e3;color:#6e5743;border:0;border-left:1px solid #c6ac7d66;box-shadow:-20px 0 70px #0002;overflow-y:auto}.journal-drawer::backdrop{background:#061d244f;backdrop-filter:blur(3px)}.journal-drawer header{display:flex;justify-content:space-between;align-items:start}.journal-drawer h2{font:26px 'KaiTi','STKaiti',serif;letter-spacing:3px;margin:12px 0 0}.drawer-note{font-size:11px;color:#9b866b;margin:17px 0 30px}.journal-entry{padding:20px 0;border-top:1px solid #bba17433}.saved-entry{display:grid;gap:10px;background:none;border:0;color:inherit;text-align:left;font:inherit;padding:0;cursor:pointer}.saved-entry small{font-size:10px;color:#a38866;letter-spacing:2px}.saved-entry strong{font:21px 'KaiTi','STKaiti',serif;letter-spacing:3px;color:#954a3e}.saved-entry span,.journal-entry p{font-size:13px;line-height:1.9;overflow-wrap:anywhere}.remove-entry{border:0;background:none;color:#ad8c6b;font-family:inherit;font-size:10px;padding:0;cursor:pointer;margin-top:16px}.wish-theme{display:flex;gap:6px;align-items:center;font-size:11px;color:#8b764f}.empty-journal{font-size:13px;line-height:2.3;color:#a28c6e;margin-top:60px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}button:disabled{opacity:.5;cursor:default}button:focus-visible{outline:2px solid #ba915a;outline-offset:4px}.is-paused .paper-background *{animation-play-state:paused}@keyframes reveal{from{opacity:0;transform:translateY(20px) rotate(-2deg)}to{opacity:1;transform:none}}@keyframes appear{from{opacity:0;margin-bottom:-10px}to{opacity:1;margin-bottom:0}}@media(max-height:720px){.fortune-heading h1{font-size:26px;margin:9px 0}.fortune-heading p{font-size:11px}.fortune-result{padding:15px 25px;margin:16px 0}.fortune-result h2{font-size:27px;margin:12px 0}.result-blessing{margin:13px auto}.result-action p{margin:7px 0 10px}.result-rule{margin:10px 0}.fortune-object{height:38vh}.fortune-stage{inset:74px 0 50px}.fortune-bottom>p{margin-top:9px}.wish-composer{bottom:10%}}@media(max-width:650px){.ritual-header{padding:15px 13px;grid-template-columns:1fr auto}.scene-tabs{display:none}.back-button span{font-size:11px}.header-tools{gap:5px}.journal-button span{display:none}.pond-heading{left:8%;top:20%}.pond-heading h1{font-size:25px;letter-spacing:3px}.ritual-footer{left:20px;right:20px;bottom:15px}.object-poem{right:-35px;font-size:12px}.fortune-heading h1{letter-spacing:2px}.fortune-heading p{max-width:270px;margin:auto}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
</style>
